class LoggingFilter @Inject() (implicit val mat: Materializer, ec: ExecutionContext)
    extends Filter {
  def apply(next: RequestHeader => Future[Result])(rh: RequestHeader): Future[Result] =
    next(rh).map(_.withHeaders("Request-Time" -> System.currentTimeMillis.toString))
}

class Filters @Inject() (log: LoggingFilter) extends DefaultHttpFilters(log)
